				PushWaza_to_EggParam(egg, WazaNo.BORUTEKKAA);
		}
		private static void DecideEggParam_Waza_MACHINE(global::Pml.PokePara.EggParam egg, global::Pml.PokePara.Parents parents) {
			for (byte i = 0; i < 4; i++)
			{
				WazaNo wazano = parents.father.GetWazaNo(i);
				for (uint itemno = (uint)ItemNo.WAZAMASIN01; itemno < (uint)ItemNo.DATA_MAX; itemno++)
				{
					if (wazano == ItemData.GetWazaNo((ushort)itemno)
						&& IsWazaMachineAbleToUse(egg.spec.monsno, egg.spec.formno, (ushort)itemno))
					{
						PushWaza_to_EggParam(egg, wazano);
						break;
					}
				}
			}
		}
		private static void DecideEggParam_BallID(global::Pml.PokePara.EggParam egg, global::Pml.PokePara.Parents parents, global::Pml.PokePara.EggGenerator.SavedRandomFunc randFunc) {
			MonsNo motherMonsNo = parents.mother.GetMonsNo();
			MonsNo fatherMonsNo = parents.father.GetMonsNo();
			uint motherBall = parents.mother.GetGetBall();
			uint fatherBall = parents.father.GetGetBall();
			uint ballID;
			if (motherMonsNo == MonsNo.METAMON)
				ballID = fatherBall;
			else if (motherMonsNo == fatherMonsNo && randFunc(100) + 1 > 50)
				ballID = fatherBall;
			else
				ballID = motherBall;

			egg.ballID = ballID;
			if (ballID == (uint)BallId.MASUTAABOORU || ballID == (uint)BallId.PURESYASUBOORU || ItemManager.IsStrangeBall((BallId)ballID))
				egg.ballID = (uint)BallId.MONSUTAABOORU;
		}
		private static bool IsWazaMachineAbleToUse(global::Pml.MonsNo monsno, ushort formno, ushort itemno) {
			if (monsno >= MonsNo.TAMAGO)
			{
				GFL.ASSERT(false);
				return false;
			}
			if (!ItemData.IsWazaMachine(itemno))
				return false;

			PersonalSystem.LoadPersonalData(monsno, formno);
			uint machineNo = ItemData.GetWazaMashineNo(itemno);
			uint machineBits;
			if (machineNo < 32)
			{
				machineBits = PersonalSystem.GetPersonalParam(ParamID.MACHINE1);
			}
			else if (machineNo < 64)
			{
				machineBits = PersonalSystem.GetPersonalParam(ParamID.MACHINE2);
				machineNo -= 32;
			}
			else if (machineNo < 96)
			{
				machineBits = PersonalSystem.GetPersonalParam(ParamID.MACHINE3);
				machineNo -= 64;
			}
			else
			{
				machineBits = PersonalSystem.GetPersonalParam(ParamID.MACHINE4);
				machineNo -= 96;
			}
			return ((1u << (int)machineNo) & machineBits) != 0;
		}
		private static void SetupEggParam(global::Pml.PokePara.CoreParam egg, global::Pml.PokePara.EggParam egg_param, global::Pml.PokePara.Parents parents, global::Pml.PokePara.EggGenerator.Setting setting) {
			bool fastMode = egg.StartFastMode();
			egg.SetParentName(setting.parentName);
			egg.SetNickName(PersonalSystem.GetMonsName(MonsNo.TAMAGO, (global::Dpr.Message.MessageEnumData.MsgLangId)PmlUse.Instance.LangId));
			for (uint i = 0; i < egg_param.wazaCount; i++)
			{
				egg.SetWaza((byte)i, egg_param.wazano[i]);
				egg.SetTamagoWazaNo((byte)i, egg_param.wazano[i]);
			}
			egg.SetGetBall(egg_param.ballID);
			egg.SetEggFlag();
			egg.EndFastMode(fastMode);
		}
		private static bool isFormInheritEnableByKawarazuNoIshi(ref ushort pFormNo, global::Pml.PokePara.CoreParam pParent) {
			if (pParent.GetItem() != (ushort)ItemNo.KAWARAZUNOISI)
				return false;

			PersonalSystem.LoadPersonalData(pParent.GetMonsNo(), pParent.GetFormNo());
			pFormNo = (ushort)PersonalSystem.GetPersonalParam(ParamID.EGG_FORM_NO_KAWARAZUNOISHI);
			return PersonalSystem.GetPersonalParam(ParamID.EGG_FORM_INHERIT_KAWARAZUNOISHI) != 0;
		}
		private static global::Pml.MonsNo GetSeedMonsNo(global::Pml.MonsNo monsno, ushort formno) {
			return (MonsNo)PersonalSystem.GetPersonalData(monsno, formno).GetParam(ParamID.EGG_MONS_NO);
		}
		public EggGenerator() { }
		static EggGenerator() { }
		public delegate uint SavedRandomFunc(uint maxValue);
		public class Setting
		{
			public uint IDNo;
			public string parentName;
			public bool haveItem_HIKARUOMAMORI;
			public global::Pml.PokePara.EggGenerator.SavedRandomFunc randFunc;
			public byte realRegionFormNo;
			public Setting() { }
		}
	}
